import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.DdJ92B9j.js";const m=JSON.parse('{"title":"工程检查与部署","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tooling.md","filePath":"guide/tooling.md"}'),c={name:"guide/tooling.md"};function r(i,e,p,n,s,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="工程检查与部署" tabindex="-1">工程检查与部署 <a class="header-anchor" href="#工程检查与部署" aria-label="Permalink to &quot;工程检查与部署&quot;">​</a></h1><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>pnpm env:check</code></td><td>校验 Node、pnpm 与依赖安装</td></tr><tr><td><code>pnpm dev</code></td><td>同步图标清单并启动 Vite</td></tr><tr><td><code>pnpm harness context</code></td><td>查任务域；追加 <code>routing</code>、<code>ui</code>、<code>api</code> 等可看实现入口和回归</td></tr><tr><td><code>pnpm harness verify ui</code></td><td>按域运行定向测试</td></tr><tr><td><code>pnpm harness verify</code></td><td>运行全量检查并生成本地报告</td></tr><tr><td><code>pnpm typecheck</code></td><td>验证图标清单，检查应用、Node 配置和测试类型</td></tr><tr><td><code>pnpm dev-build</code> / <code>pnpm report</code></td><td>构建开发版，或输出静态打包报告</td></tr><tr><td><code>pnpm build</code> / <code>pnpm preview</code></td><td>构建并在本机验收产物</td></tr><tr><td><code>pnpm packages:check</code></td><td>检查公开入口、依赖声明和循环依赖</td></tr><tr><td><code>pnpm pages:build</code></td><td>将后台与文档组装到 <code>dist/pages</code></td></tr><tr><td><code>pnpm docs:dev</code></td><td>启动文档开发站</td></tr><tr><td><code>pnpm docs:check</code></td><td>验证文档示例类型、站内链接与生产构建</td></tr><tr><td><code>pnpm docs:preview</code></td><td>预览已构建的文档站</td></tr></tbody></table><p>全量检查包含环境、Harness、图标同步、类型、ESLint、Prettier、Vitest 和生产构建。Harness 在 <code>.harness-local/runs/</code> 写结果；Chrome 验收单独记录。改动交互或布局时，额外验收中英文、明暗主题和窄屏。</p><h2 id="部署到子路径" tabindex="-1">部署到子路径 <a class="header-anchor" href="#部署到子路径" aria-label="Permalink to &quot;部署到子路径&quot;">​</a></h2><p><code>pnpm build</code> 输出 <code>dist/production</code>。将产物部署到与 <code>vite.custom.config.ts</code> 中 <code>base</code> 对应的路径。默认应用为 <code>/ray-template/</code>，域名根目录部署改为 <code>/</code>。Vite 默认打包本地依赖；可选 CDN 模式需另外确认目标环境能访问 CDN。</p><p>组合部署使用 <code>pnpm pages:build</code>，将 <code>dist/pages</code> 作为同一个站点的产物。官方地址为 <code>/ray-template/</code>，其下 <code>docs/</code> 目录提供 v6 官网。CI 传入 <code>RAY_TEMPLATE_SOURCE_REF</code>，把文档的当前源码链接固定到发布提交。</p><p>公开生产部署可在构建环境设置 <code>RAY_TEMPLATE_SITE_ORIGIN</code> 为实际站点源地址（例如 <code>https://example.com</code>），由 base 补足路径。未配置时应用产物使用 <code>noindex</code>。公开 sitemap 列出入口页，登录后的 hash 路由用于应用交互。</p><h2 id="二次开发约定" tabindex="-1">二次开发约定 <a class="header-anchor" href="#二次开发约定" aria-label="Permalink to &quot;二次开发约定&quot;">​</a></h2><ul><li>新页面遵循 Vue 3 Composition API + TSX 或现有 SFC 模式。复用现有组件，声明按职责归档。</li><li>Vue、Router、Pinia 的自动导入声明由生成器维护；类型使用 <code>import type</code>。应用、测试、Node 配置的 TS 边界不同。</li><li>格式由 Prettier 管理，ESLint 使用 flat config。提交约定和注释写法以应用仓库当前规则为准。</li></ul><p><a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/40320207ac6649076457fdcf33fbe04181d6288a/docs/architecture.md" target="_blank" rel="noreferrer">工程与部署入口</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/40320207ac6649076457fdcf33fbe04181d6288a/harness/README.md" target="_blank" rel="noreferrer">AI Harness</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/40320207ac6649076457fdcf33fbe04181d6288a/docs/comment-style.md" target="_blank" rel="noreferrer">注释规范</a></p>',11)])])}const u=t(c,[["render",r]]);export{m as __pageData,u as default};
